mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def token():
    global tok
    tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST")))["token"]
def get(p):
    while True:
        if tok is None: token()
        try: return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            if e.code==401: token()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404: return None
            else: notes.append((p,e.code)); time.sleep(1)
        except Exception as e: notes.append((p,str(e))); time.sleep(1)
orders={};dups=0;p="/orders?page=1";n=0
while p:
    d=get(p);n+=1
    for o in d["items"]:
        if o["id"] in orders: dups+=1
        else: orders[o["id"]]=o
    p=d["next"]
cust={};tot=0;cnt=0;reg={k:0 for k in["north","south","east","west"]};lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
naive=0;stat=set()
for o in orders.values():
    stat.add(o["status"])
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: naive+=1;t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    C=cust[c]
    if C is None: print("missing cust",c,o);continue
    v=(o["amount_cents"]*(100-C["discount_pct"])+50)//100
    tot+=v;cnt+=1;reg[C["region"]]+=v
json.dump({"total_cents":tot,"order_count":cnt,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(n,d.get("total_pages"),len(orders),dups,naive,stat,notes[:10],len(notes),open("/workspace/result.json").read())
EOF
python3 -I /tmp/work/r.py

